/* Kehillat Noam | the public screens: landing, davening times (+ the gabbai's editor),
   the TV page, donations (a simulated payment), thanks, join, notifications, the brochure. */
(function () {
  "use strict";
  var KN = window.KN, D = window.KN_DATA, S = KN.S, T = KN.T, L = KN.L, esc = KN.esc, ic = KN.ic, W = D.WEEK, B = D.B;
  function monthCollected() { var s = 0; S.members.forEach(function (m) { m.ledger.forEach(function (e) { if (e.type === "payment" && e.date.slice(0, 7) === "2026-11") s += e.amount; }); }); S.donations.forEach(function (d) { if (d.date.slice(0, 7) === "2026-11") s += d.amount; }); return Math.round(s); }
  KN.monthCollected = monthCollected;
  /* one source for every money trend: the months before the sample ledger come from D.history, the rest are summed from the ledger */
  KN.monthSeries = function () {
    var sum = { "2026-09": 0, "2026-10": 0, "2026-11": 0 };
    S.members.forEach(function (m) { m.ledger.forEach(function (e) { var k = e.date.slice(0, 7); if (e.type === "payment" && k in sum) sum[k] += e.amount; }); });
    S.donations.forEach(function (d) { var k = d.date.slice(0, 7); if (k in sum) sum[k] += d.amount; });
    return D.history.map(function (h) { return [h[0], h[1]]; }).concat([[B("ספט׳", "Sep"), Math.round(sum["2026-09"])], [B("אוק׳", "Oct"), Math.round(sum["2026-10"])], [B("נוב׳", "Nov"), Math.round(sum["2026-11"])]]);
  };
  KN.monthDelta = function () { var m = KN.monthSeries(), o = m[4][1] || 1; return Math.round((m[5][1] / o - 1) * 100); };
  KN.deltaHtml = function () { var d = KN.monthDelta(); return (d >= 0 ? "▲ " : "▼ ") + Math.abs(d) + "% " + T("מול אוקטובר", "vs October"); };
  /* one campaign, no funds: every donation counts toward it, on every screen */
  KN.campaign = function () {
    var C = D.campaign, raised = Math.round(C.base + S.donations.reduce(function (a, d) { return a + d.amount; }, 0));
    return { name: L(C.name), goal: C.goal, raised: raised, pct: Math.min(100, raised / C.goal * 100), donors: C.baseDonors + S.donations.length, days: Math.max(0, Math.ceil((KN.at(C.end, "23:59") - KN.now().getTime()) / 864e5)) };
  };
  KN.campHtml = function (id) {
    var c = KN.campaign();
    return '<div class="camp-n"><b>' + KN.moneyT(c.raised) + "</b><span>" + T("מתוך ", "of ") + KN.moneyT(c.goal) + '</span></div><div class="thermo"><i id="' + id + '" data-w="' + c.pct.toFixed(2) + '"></i><em style="inset-inline-start:25%"></em><em style="inset-inline-start:50%"></em><em style="inset-inline-start:75%"></em></div><div class="camp-f"><span><b>' + c.pct.toFixed(1) + "%</b> " + T("מהיעד", "of goal") + "</span><span><b>" + c.donors + "</b> " + T("תורמים", "donors") + "</span><span><b>" + c.days + "</b> " + T("ימים נותרו", "days left") + "</span></div>";
  };
  KN.campFill = function (id, instant) { var t = document.getElementById(id); if (!t) return; if (instant) t.style.transition = "none"; t.style.width = t.dataset.w + "%"; };
  KN.cta = function () {
    return '<section class="section"><div class="cta"><div><h2>' + T("רוצים את זה לבית הכנסת שלכם?", "Want this for your synagogue?") + "</h2><p>" +
      T("אותה מערכת, עם השם, הלוגו והצבעים שלכם. אנחנו מקימים אותה יחד איתכם, בלי ציוד חדש חוץ מטלוויזיה. דברו איתנו ונראה לכם איך זה נראה אצלכם.", "The same system, with your name, your logo and your colors. We set it up with you, no new hardware except a TV. Talk to us and we will show you how it looks for your shul.") +
      '</p></div><div class="cta-box"><a href="tel:' + D.sales.tel + '">' + ic("phone") + '<bdi class="ltr">' + D.sales.phone + '</bdi></a><a class="alt" href="mailto:' + D.sales.email + '">' + ic("mail") + '<bdi class="ltr">' + D.sales.email + "</bdi></a></div></div></section>";
  };
  function foot() { return '<p class="center top-inline"><button class="btn sm sec" data-act="toTop">' + ic("up") + T("חזרה למעלה", "Back to top") + '</button></p><p class="center small muted" style="margin-top:34px">' + T("זו הדגמה. בית הכנסת, האנשים, הסכומים וההקדשות בדויים כולם. שום תשלום אינו אמיתי.", "This is a demo. The synagogue, the people, the amounts and the dedications are all invented. No payment is real.") + " " + T("הדמו פתוח לגמרי: בלי הרשמה, בלי שיחת מכירה.", "The demo is fully open: no sign-up, no sales call.") + "</p>"; }
  KN.foot = foot;
  function tvFrame(id, cap) { return '<div class="tvframe"><div class="tvhost" id="' + id + '" data-go="tv" title="' + T("לפתוח את המסך", "Open the screen") + '"></div></div>' + (cap || ""); }
  KN.tvFrame = tvFrame;

  /* the landing page itself lives in landing.js */
  KN.act.contactMsg = function () {
    KN.modal("<h2>" + T("הודעה לגבאי", "A message to the gabbai") + '</h2><div class="stack" style="margin-top:14px"><div class="field"><label for="cmName">' + T("שם", "Name") + '</label><input class="input" id="cmName" value="' + T("אורח מההדגמה", "Demo visitor") + '"></div><div class="field"><label for="cmText">' + T("ההודעה", "Message") + '</label><textarea class="input" id="cmText">' + T("שלום, נשמח לדעת מתי שיעור הדף היומי בשבת.", "Hello, when is the Daf Yomi shiur on Shabbat?") + '</textarea></div><button class="btn" data-act="contactSend">' + T("שליחה", "Send") + "</button></div>");
  };
  KN.act.contactSend = function () { KN.closeModal(); KN.notify({ kind: "announce", title: B("הודעה מטופס יצירת הקשר", "A message from the contact form"), body: B("אורח מההדגמה שאל על שיעור הדף היומי", "A demo visitor asked about the Daf Yomi shiur"), to: ["admin", "content"] }); KN.toast(T("ההודעה נשלחה לגבאי (בהדגמה: לפעמון של המנהל)", "Message sent to the gabbai (in the demo: to the admin's bell)")); };

  /* ================= davening times ================= */
  var tSel = null;
  function cell(dow, kind) { var l = KN.dayPrayers(dow).filter(function (p) { return p.kind === kind; }); return l.length ? l.map(function (p) { return '<span class="num">' + KN.time(p.time) + "</span>"; }).join(" · ") : '<span class="muted">-</span>'; }
  KN.views.times = {
    render: function (arg) {
      if (arg === "edit") return KN.can("content") ? editor() : KN.lockPage("content");
      var today = KN.today(), sel = W.days[tSel == null ? today.dow : tSel], ps = KN.dayPrayers(sel.dow);
      return '<div class="page"><div class="page-head"><div><span class="eyebrow">' + T("זמני תפילה וזמני היום", "Davening times & daily zmanim") + "</span><h1>" + T("שבוע פרשת ", "The week of Parashat ") + esc(L(W.parasha)) + '</h1><p class="lede">' + T("היום: יום ", "Today: ") + L(D.DOW[today.dow]) + ", " + KN.hdate(today.hDay, 2) + " " + L(W.hYear) + " · " + L(today.g) + ' 2026</p></div><button class="btn sec" data-go="times/edit">' + ic("edit") + T("לגבאי: עריכת הזמנים", "For the gabbai: edit times") + (KN.can("content") ? "" : ic("lock")) + "</button></div>" +
        '<div class="split"><div class="stack"><div class="card"><div class="card-h"><h2>' + T("השבוע בבית הכנסת", "This week at the shul") + '</h2></div><div class="tw"><table class="t week"><tr><th>' + T("יום", "Day") + "</th><th>" + T("תאריך", "Date") + "</th><th>" + T("שחרית", "Shacharit") + "</th><th>" + T("מנחה", "Mincha") + "</th><th>" + T("ערבית", "Maariv") + "</th></tr>" +
        W.days.map(function (d) { var td = d.dow === today.dow ? ' class="today"' : ""; return "<tr><td" + td + "><b>" + L(D.DOW[d.dow]) + (d.dow === today.dow ? ' <span class="chip gold">' + T("היום", "Today") + "</span>" : "") + "</b></td><td" + td + ">" + KN.hdate(d.hDay, 2) + '<div class="small muted">' + L(d.g) + "</div></td><td" + td + ">" + cell(d.dow, "shacharit") + "</td><td" + td + ">" + cell(d.dow, "mincha") + "</td><td" + td + ">" + cell(d.dow, "maariv") + "</td></tr>"; }).join("") + "</table></div></div>" +
        '<div class="card"><div class="card-h"><h2>' + T("זמני היום", "Daily zmanim") + '</h2></div><div class="daytabs" role="tablist">' + W.days.map(function (d) { return '<button data-act="tDay" data-d="' + d.dow + '" role="tab" aria-selected="' + (d.dow === sel.dow) + '"><b>' + L(D.DOW_S[d.dow]) + "</b><span>" + KN.hdate(d.hDay, 2) + "</span></button>"; }).join("") + '</div><div class="grid g2" style="margin-top:14px"><div><p class="lbl">' + T("זמני היום · ", "Zmanim · ") + L(D.DOW[sel.dow]) + '</p><div class="zlist">' + KN.zRows(sel.iso).replace(/<div><span>/g, "<div>").replace(/<\/span><b>/g, "</div><div>").replace(/<\/b><\/div>/g, "</div>") + '</div></div><div><p class="lbl">' + T("תפילות · ", "Davening · ") + L(D.DOW[sel.dow]) + '</p><div class="zlist">' + ps.map(function (p) { return "<div>" + esc(L(p.name)) + "</div><div>" + KN.time(p.time) + "</div>"; }).join("") + '</div><p class="note" style="margin-top:12px">' + T("הזמנים מחושבים למיקום של בית הכנסת. בהדגמה: מיקום לדוגמה.", "Zmanim are calculated for the shul's location. In the demo: a sample location.") + "</p></div></div></div></div>" +
        '<div class="stack"><div class="shab-card"><span class="eyebrow" style="color:var(--a-soft)">' + T("שבת קודש", "Shabbat") + "</span><h3>" + T("שבת פרשת ", "Shabbat Parashat ") + esc(L(W.parasha)) + '</h3><p style="opacity:.8">' + KN.hdate(11, 2) + " " + L(W.hYear) + " · " + T("21 בנובמבר 2026", "Nov 21, 2026") + '</p><div class="big3"><div><b>' + KN.time(W.candle) + "</b><span>" + T("הדלקת נרות", "Candle lighting") + "</span></div><div><b>" + KN.time(W.ends) + "</b><span>" + T("צאת השבת", "Shabbat ends") + "</span></div><div><b>" + KN.time(W.rt) + "</b><span>" + T("רבנו תם", "Rabbeinu Tam") + '</span></div></div><div style="margin-top:14px;border-top:1px solid rgba(255,255,255,.2);padding-top:10px">' + KN.dayPrayers(5).filter(function (p) { return p.kind !== "shacharit"; }).concat(KN.dayPrayers(6)).map(function (p) { return '<div style="display:flex;justify-content:space-between;padding:3px 0"><span>' + esc(L(p.name)) + "</span><b>" + KN.time(p.time) + "</b></div>"; }).join("") + "</div></div>" +
        '<div class="card"><h3>' + T("מועדים קרובים", "Upcoming holidays") + '</h3><div style="margin-top:8px">' + D.holidays.map(function (h) { return '<div class="item"><span class="avatar" style="background:var(--a-tint);color:var(--a-text)">' + ic("cal") + '</span><div class="grow"><b style="color:var(--p)">' + esc(L(h.name)) + '</b><div class="small">' + esc(L(h.when)) + '</div><div class="small muted">' + esc(L(h.note)) + "</div></div></div>"; }).join("") + '</div></div><div class="card"><h3>' + T("שיעורי תורה", "Shiurim") + "</h3>" + D.shiurim.map(function (s) { return '<div class="item"><b class="num" style="color:var(--p);min-width:74px">' + KN.time(s.t) + '</b><div class="grow"><b>' + esc(L(s.name)) + '</b><div class="small muted">' + esc(L(s.who)) + "</div></div></div>"; }).join("") + "</div></div></div>" + foot() + "</div>";
    },
    after: function (root, arg) { if (arg === "edit" && KN.can("content")) KN.tvMount(document.getElementById("edTv")); }
  };
  KN.act.tDay = function (el) { tSel = +el.dataset.d; KN.render(); };
  function editor() {
    var kinds = { shacharit: T("שחרית", "Shacharit"), mincha: T("מנחה", "Mincha"), maariv: T("ערבית", "Maariv") };
    return '<div class="page wide"><div class="page-head"><div><span class="eyebrow">' + T("עורך זמני התפילה · גבאי תוכן", "Davening-times editor · content gabbai") + "</span><h1>" + T("משנים זמן, וזה מתעדכן בכל מקום", "Change a time, and it updates everywhere") + '</h1><p class="lede">' + T("כל שינוי כאן מופיע מיד בדף הזמנים ובמסך שמשמאל, והמתפללים מקבלים התראה. השינויים נשארים בהדגמה בלבד.", "Every change here shows at once on the times page and on the screen beside it, and the members get a notification. Changes stay inside the demo.") + '</p></div><button class="btn sec" data-go="times">' + T("חזרה לדף הזמנים", "Back to the times page") + '</button></div><div class="editor"><div class="stack"><div class="card"><div class="card-h"><h2>' + T("המניינים", "The minyanim") + "</h2></div>" +
      S.prayers.map(function (p) { var auto = p.rule === "motzash" && S.motzashRule;
        return '<div class="ed-row"><div><b style="color:var(--p)">' + esc(L(p.name)) + '</b><div class="small muted">' + kinds[p.kind] + '</div></div><input type="text" inputmode="numeric" maxlength="5" dir="ltr" placeholder="18:15" class="input num" style="text-align:center" aria-label="' + T("שעה", "Time") + '" data-on="pTime" data-id="' + p.id + '" value="' + (auto ? KN.hhmm(KN.mins(W.ends) - 3) : p.time) + '"' + (auto ? " disabled" : "") + '><div class="dow" role="group" aria-label="' + T("ימים", "Days") + '">' + D.DOW_S.map(function (d, i) { return '<button data-act="pDay" data-id="' + p.id + '" data-d="' + i + '" aria-pressed="' + (p.days.indexOf(i) >= 0) + '">' + L(d) + "</button>"; }).join("") + '</div><button class="iconbtn" data-act="pDel" data-id="' + p.id + '" aria-label="' + T("מחיקה", "Delete") + '">' + ic("trash") + "</button></div>"; }).join("") + "</div>" +
      '<div class="card gold"><h3>' + T("כלל השבת", "The Shabbat rule") + '</h3><label class="switch" style="margin-top:10px"><input type="checkbox" data-on="pRule"' + (S.motzashRule ? " checked" : "") + "><i></i><span>" + T("ערבית של מוצאי שבת: 3 דקות לפני צאת השבת, אוטומטית", "Maariv on Motzei Shabbat: 3 minutes before Shabbat ends, automatically") + '</span></label><p class="small muted" style="margin-top:8px">' + T("השבת יוצאת ב־", "Shabbat ends at ") + KN.time(W.ends) + T(", ולכן ערבית ב־", ", so Maariv is at ") + "<b>" + KN.time(KN.hhmm(KN.mins(W.ends) - 3)) + "</b>" + T(". בשבוע הבא הזמן יזוז לבד עם צאת השבת.", ". Next week the time moves by itself with the end of Shabbat.") + "</p></div>" +
      '<div class="card"><h3>' + T("הוספת מניין", "Add a minyan") + '</h3><div class="grid g2" style="margin-top:10px"><div class="field"><label for="npHe">' + T("שם בעברית", "Name in Hebrew") + '</label><input class="input" id="npHe" value="מנחה גדולה"></div><div class="field"><label for="npEn">' + T("שם באנגלית", "Name in English") + '</label><input class="input" id="npEn" value="Early Mincha" dir="ltr"></div><div class="field"><label for="npKind">' + T("סוג", "Kind") + '</label><select class="input" id="npKind"><option value="mincha">' + kinds.mincha + '</option><option value="shacharit">' + kinds.shacharit + '</option><option value="maariv">' + kinds.maariv + '</option></select></div><div class="field"><label for="npTime">' + T("שעה", "Time") + '</label><input type="text" inputmode="numeric" maxlength="5" dir="ltr" placeholder="18:15" class="input num" id="npTime" value="13:15"></div></div><p class="small muted" style="margin:10px 0">' + T("המניין יתווסף לימים ראשון עד חמישי. אפשר לשנות ימים בשורה שלו.", "The minyan is added for Sunday to Thursday. Change its days on its row.") + '</p><button class="btn" data-act="pAdd">' + ic("plus") + T("הוספה", "Add") + '</button></div></div><div class="sticky">' + KN.tvFrame("edTv", '<p class="tv-cap"><span class="live"><i></i>' + T("המסך מתעדכן תוך כדי עריכה", "The screen updates as you edit") + "</span></p>") + "</div></div></div>";
  }
  function pById(id) { return S.prayers.filter(function (p) { return p.id === id; })[0]; }
  function timesChanged(p, quiet) { KN.save(); KN.tvRefresh(); if (!quiet) { KN.notify({ kind: "times", title: B("שינוי בזמני התפילה", "Davening time changed"), body: B(p.name.he + ": " + KN.time(p.time).replace(/ (AM|PM)/, ""), p.name.en + ": " + KN.time(p.time)), to: ["member", "finance", "content", "admin"] }); KN.toast(T("הזמן עודכן באתר ובמסך, והמתפללים קיבלו התראה", "Time updated on the site and the screen; members were notified")); } }
  function hm(v) { var m = /^([01]?\d|2[0-3]):([0-5]\d)$/.exec(String(v).trim()); return m ? (m[1].length < 2 ? "0" + m[1] : m[1]) + ":" + m[2] : ""; }
  KN.on.pTime = function (el) { var p = pById(el.dataset.id), t = hm(el.value); el.classList.toggle("bad", !t); if (!p || !t || t === p.time) return; p.time = t; timesChanged(p); };
  KN.act.pDay = function (el) { var p = pById(el.dataset.id), d = +el.dataset.d, i = p.days.indexOf(d); if (i >= 0) p.days.splice(i, 1); else p.days.push(d); p.days.sort(); el.setAttribute("aria-pressed", String(i < 0)); KN.save(); KN.tvRefresh(); KN.toast(T("ימי המניין עודכנו", "The minyan's days were updated")); };
  KN.act.pDel = function (el) { var p = pById(el.dataset.id); S.prayers = S.prayers.filter(function (x) { return x !== p; }); KN.save(); KN.render(); KN.toast(T("המניין הוסר", "The minyan was removed")); };
  KN.on.pRule = function (el) { S.motzashRule = el.checked; KN.save(); KN.render(); KN.toast(el.checked ? T("הכלל פעיל: ערבית 3 דקות לפני צאת השבת", "Rule on: Maariv 3 minutes before Shabbat ends") : T("הכלל כבוי: השעה נקבעת ידנית", "Rule off: the time is set by hand")); };
  KN.act.pAdd = function () {
    var he = document.getElementById("npHe").value.trim(), en = document.getElementById("npEn").value.trim(), t = hm(document.getElementById("npTime").value);
    if (!he || !t) { KN.toast(T("חסר שם או שעה", "A name or a time is missing")); return; }
    var p = { id: "p" + Date.now(), kind: document.getElementById("npKind").value, name: B(he, en || he), days: [0, 1, 2, 3, 4], time: t };
    S.prayers.push(p); KN.render(); timesChanged(p);
  };

  /* ================= the TV page ================= */
  KN.views.tv = {
    render: function () {
      return '<div class="tvpage"><div class="page-head" style="margin-bottom:12px"><div><span class="eyebrow">' + T("מסך בית הכנסת · פועל תמיד", "The shul screen · always on") + '</span><h2>' + T("הזיזו את השעון וצפו במסך מתחלף מעצמו", "Move the clock and watch the screen switch by itself") + '</h2></div><div class="row"><button class="btn sm sec" data-act="tvFull">' + ic("tv") + T("מסך מלא", "Full screen") + '</button><button class="btn sm sec" data-act="customize">' + ic("palette") + T("להחליף מראה", "Change the look") + '</button></div></div><div class="tvctl" role="group" aria-label="' + T("שעון ההדגמה", "Demo clock") + '"><span class="lbl">' + T("שעון ההדגמה:", "Demo clock:") + "</span>" + KN.PRESETS.map(function (p) { return '<button data-act="tvClock" data-p="' + p.id + '" aria-pressed="' + (S.clock === p.id) + '">' + T(p.he, p.en) + "</button>"; }).join("") + '</div><div class="tvframe" style="margin-top:14px"><div class="tvhost" id="bigTv"></div></div>' +
        '<div class="grid g3" style="margin-top:34px"><div class="card"><h3>' + ic("list") + " " + T("בימי חול", "On weekdays") + '</h3><p class="small" style="margin-top:6px">' + T("המרכז מתחלף: הקדשות, יארצייט, אזכרות, מזל טוב, הודעות ולוח הקידושים. קוד ה־QR מוביל לדף התרומה, והספירה לאחור להדלקת נרות רצה.", "The centre rotates: dedications, yahrzeits, memorials, mazal tov, announcements and the kiddush board. The QR opens the donate page, and the countdown to candle lighting runs.") + '</p></div><div class="card gold"><h3>' + ic("flame") + " " + T("בשבת", "On Shabbat") + '</h3><p class="small" style="margin-top:6px">' + T("ברגע הדלקת הנרות המסך עובר לבד למצב שבת: ״שבת שלום״ עם נרות, בלי QR, בלי תנועה. ההקדשות והיארצייט נשארים. אף אחד לא נוגע במסך.", "At candle lighting the screen switches by itself: Shabbat Shalom with candles, no QR, nothing moving. The dedications and yahrzeits stay. Nobody touches the screen.") + '</p></div><div class="card"><h3>' + ic("star") + " " + T("במוצאי שבת", "On Saturday night") + '</h3><p class="small" style="margin-top:6px">' + T("עם צאת השבת המסך חוזר למצב חול: ״שבוע טוב״, ה־QR חוזר, וההודעות שוב מתחלפות.", "When Shabbat ends the screen returns to weekday mode: Shavua Tov, the QR is back, and the announcements rotate again.") + "</p></div></div>" + foot() + "</div>";
    },
    after: function () { KN.tvMount(document.getElementById("bigTv"), { onMode: function (m) { KN.toast(m === "shabbat" ? T("הדלקת נרות: המסך עבר למצב שבת מעצמו", "Candle lighting: the screen switched to Shabbat by itself") : m === "motzash" ? T("השבת יצאה: המסך חזר למצב חול", "Shabbat ended: the screen is back in weekday mode") : T("המסך התעדכן", "The screen updated")); document.querySelectorAll(".tvctl button").forEach(function (b) { b.setAttribute("aria-pressed", "false"); }); } }); }
  };
  KN.act.tvClock = function (el) { KN.setClock(el.dataset.p); KN.toast(T("השעון הוזז: ", "Clock moved: ") + el.textContent); };
  KN.act.tvFull = function () { var h = document.getElementById("bigTv"); if (h && h.requestFullscreen) h.requestFullscreen().catch(function () { KN.toast(T("הדפדפן לא אישר מסך מלא", "The browser did not allow full screen")); }); };

  /* ================= donations ================= */
  var dn = { amount: 36, fee: false, method: "card" };
  var DON = B("תרומה", "Donation");
  KN.DON = DON;
  function dnCalc() { var a = Math.max(0, Number(dn.amount) || 0), total = dn.fee && a > 0 ? Math.round((a + 0.3) / (1 - 0.029) * 100) / 100 : a; return { a: a, fee: Math.round((total - a) * 100) / 100, total: total }; }
  function dnSum() { var c = dnCalc(); return "<div><span>" + T("תרומה", "Donation") + "</span><b>" + KN.money(c.a) + "</b></div><div><span>" + T("כיסוי עמלת הסליקה", "Card-fee cover") + "</span><b>" + (dn.fee ? KN.money(c.fee) : T("לא נבחר", "not selected")) + '</b></div><div class="tot"><span>' + T("סך הכול לחיוב", "Total to charge") + "</span><b>" + KN.money(c.total) + "</b></div>"; }
  KN.views.donate = {
    render: function () {
      if (KN.isShabbat()) return '<div class="page"><div class="card gold lock-page"><div class="big">' + ic("flame") + "</div><h2>" + T("שבת שלום", "Shabbat Shalom") + '</h2><p class="lede" style="margin:8px auto 18px">' + T("לפי שעון ההדגמה עכשיו שבת, ובשבת דף התרומות סגור, בדיוק כמו במערכת האמיתית. הוא נפתח מעצמו במוצאי שבת.", "By the demo clock it is Shabbat now, and on Shabbat the donate page is closed, exactly as in the real system. It reopens by itself when Shabbat ends.") + '</p><button class="btn" data-act="dnMotzash">' + T("להזיז את השעון למוצאי שבת", "Move the clock to Saturday night") + "</button></div></div>";
      var me = KN.me();
      setTimeout(function () { KN.campFill("dnThermo"); }, 150);
      return '<div class="page"><div class="page-head"><div><span class="eyebrow">' + T("תרומה לבית הכנסת", "Donate to the shul") + "</span><h1>" + T("תרומה ל", "Donate to ") + esc(KN.shulName()) + '</h1><p class="lede">' + T("תרומה מאובטחת בכרטיס אשראי, עם קבלה למס במייל מיד אחרי התשלום.", "A secure card donation, with a tax receipt by email right after the payment.") + '</p></div></div><div class="split"><div class="card stack"><div><p class="lbl" style="margin-bottom:8px">' + T("סכום התרומה", "Donation amount") + '</p><div class="amts">' + [18, 36, 100, 180, 360].map(function (a) { return '<button data-act="dnAmt" data-a="' + a + '" aria-pressed="' + (dn.amount === a) + '">$' + a + "</button>"; }).join("") + '</div><div class="field" style="margin-top:10px"><label for="dnOther">' + T("סכום אחר ($)", "Other amount ($)") + '</label><input class="input num" id="dnOther" inputmode="decimal" data-on="dnOther" value="' + ([18, 36, 100, 180, 360].indexOf(dn.amount) < 0 ? dn.amount : "") + '" aria-label="' + T("סכום אחר", "Other amount") + '"></div></div>' +
        '<label class="check"><input type="checkbox" data-on="dnFee"' + (dn.fee ? " checked" : "") + "><span><b>" + T("אני מוסיף את עמלת הסליקה", "I will cover the card fee") + '</b><br><span class="small muted">' + T("כך כל התרומה מגיעה לבית הכנסת (2.9% + 30 סנט).", "So the whole donation reaches the shul (2.9% + 30 cents).") + "</span></span></label>" +
        '<div class="paytabs" role="tablist"><button role="tab" data-act="dnMethod" data-m="card" aria-selected="' + (dn.method === "card") + '">' + T("כרטיס אשראי", "Credit card") + '</button><button role="tab" data-act="dnMethod" data-m="zelle" aria-selected="' + (dn.method === "zelle") + '">Zelle</button></div>' +
        (dn.method === "card" ? '<div class="wallets"><button class="wallet" data-act="dnPay" data-w="Apple Pay">Apple Pay</button><button class="wallet g" data-act="dnPay" data-w="Google Pay"><bdi class="ltr"><b style="color:#4285f4">G</b>oogle Pay</bdi></button></div><div class="or">' + T("או בכרטיס", "or by card") + '</div><div class="grid g2"><div class="field"><label for="dnName">' + T("שם מלא", "Full name") + '</label><input class="input" id="dnName" autocomplete="off" value="' + esc(me ? L(me.name) : "") + '"></div><div class="field"><label for="dnEmail">' + T("אימייל לקבלה", "Email for the receipt") + '</label><input class="input" id="dnEmail" dir="ltr" autocomplete="off" value="' + esc(me ? me.email : "") + '"></div></div><div class="cardgrid"><div class="field"><label for="dnCard">' + T("מספר כרטיס", "Card number") + '</label><input class="input num" id="dnCard" inputmode="numeric" autocomplete="off"></div><div class="field"><label for="dnExp">' + T("תוקף", "Expiry") + '</label><input class="input num" id="dnExp" autocomplete="off"></div><div class="field"><label for="dnCvv">CVV</label><input class="input num" id="dnCvv" autocomplete="off"></div></div><div class="row"><button class="btn sm sec" data-act="dnFill">' + T("למלא פרטי דוגמה", "Fill sample details") + '</button><span class="small muted">' + T("הדמיה: שום כרטיס אינו מחויב, ושום פרט אינו נשלח לשום מקום.", "Simulation: no card is charged and nothing is sent anywhere.") + '</span></div><button class="btn lg block" data-act="dnPay" id="dnGo">' + ic("lock") + '<span id="dnGoT">' + T("לתרום ", "Donate ") + KN.moneyT(dnCalc().total) + "</span></button>"
          : '<div class="zelle"><p class="muted">' + T("שלחו ב־Zelle אל", "Send by Zelle to") + '</p><b><bdi class="ltr">' + esc(S.shul.zelle) + '</bdi></b><p class="small muted" style="margin:8px 0 12px">' + T("כתבו בהערה את שמכם. הגבאי רושם את התשלום כשהוא מגיע, ואתם מקבלים התראה.", "Write your name in the memo. The gabbai records the payment when it arrives, and you get a notification.") + '</p><button class="btn sec" data-act="dnCopy">' + T("העתקת הכתובת", "Copy the address") + "</button></div>") + "</div>" +
        '<div class="stack"><div class="card"><h3>' + T("סיכום", "Summary") + '</h3><div class="sum" id="dnSum" style="margin-top:10px">' + dnSum() + '</div><p class="small muted" style="margin-top:10px">' + T("הקבלה למס נשלחת למייל מיד. התרומה מופיעה אצל גבאי הכספים תוך שניות.", "The tax receipt is emailed at once. The donation shows on the finance gabbai's desk within seconds.") + '</p></div><div class="card camp"><div class="card-h"><h3>' + ic("target") + esc(KN.campaign().name) + '</h3><span class="chip gold">' + T("נתוני דמו", "Demo data") + '</span></div><div id="dnCamp">' + KN.campHtml("dnThermo") + '</div><p class="small muted" style="margin-top:8px">' + T("כל תרומה נספרת בקמפיין. אין קרנות נפרדות.", "Every donation counts toward the campaign. There are no separate funds.") + '</p></div><div class="card navy"><h3>' + T("לאן הולכת התרומה", "Where your donation goes") + '</h3><p class="muted" style="margin-top:6px">' + T("אחזקת בית הכנסת, שיעורי התורה, הקידושים ופעולות החסד של הקהילה.", "The upkeep of the shul, the shiurim, the kiddushim and the community's chesed work.") + '</p></div><div class="card"><h3>' + T("הסיפור המלא בהדגמה", "The full story in the demo") + '</h3><p class="small" style="margin-top:6px">' + T("1. תורמים כאן. 2. מגיעים לדף התודה עם מספר קבלה. 3. עוברים לתפקיד גבאי כספים ורואים את התרומה בספרים ובפעמון.", "1. Donate here. 2. Land on the thanks page with a receipt number. 3. Switch to the finance gabbai and see it in the books and on the bell.") + "</p></div></div></div>" + foot() + "</div>";
    }
  };
  function dnRefresh() { var s = document.getElementById("dnSum"); if (s) s.innerHTML = dnSum(); var g = document.getElementById("dnGoT"); if (g) g.textContent = T("לתרום ", "Donate ") + KN.moneyT(dnCalc().total); }
  KN.act.dnMotzash = function () { KN.setClock("motzash"); KN.toast(T("מוצאי שבת: דף התרומות נפתח", "Saturday night: the donate page is open")); };
  KN.act.dnAmt = function (el) { dn.amount = +el.dataset.a; document.querySelectorAll(".amts button").forEach(function (b) { b.setAttribute("aria-pressed", String(b === el)); }); var o = document.getElementById("dnOther"); if (o) o.value = ""; dnRefresh(); };
  KN.on.dnOther = function (el) { el.value = el.value.replace(/[^\d.]/g, ""); dn.amount = Number(el.value) || 0; document.querySelectorAll(".amts button").forEach(function (b) { b.setAttribute("aria-pressed", "false"); }); dnRefresh(); };
  KN.on.dnFee = function (el) { dn.fee = el.checked; dnRefresh(); };
  KN.act.dnMethod = function (el) { dn.method = el.dataset.m; KN.render(); };
  KN.act.dnCopy = function () { try { navigator.clipboard.writeText(S.shul.zelle); } catch (e) {} KN.toast(T("כתובת ה־Zelle הועתקה", "The Zelle address was copied")); };
  KN.act.dnFill = function () { var v = { dnName: T("יונתן ברוך", "Jonathan Baruch"), dnEmail: "jonathan.baruch@mail.demo", dnCard: "4242 4242 4242 4242", dnExp: "12/28", dnCvv: "123" }; Object.keys(v).forEach(function (k) { var e = document.getElementById(k); if (e && (!e.value || k.indexOf("dnC") === 0 || k === "dnExp")) e.value = v[k]; }); KN.toast(T("מולאו פרטי דוגמה", "Sample details filled in")); };
  /* the simulated payment: validation, a processing step, then the thanks page. Nothing is charged. */
  KN.donate = function (o) {
    var c = dnCalc(), id = "G" + Date.now(), ref = KN.nextRef(), nm = /^(יונתן ברוך|Jonathan Baruch)$/.test(o.name) ? B("יונתן ברוך", "Jonathan Baruch") : /^(תורם בארנק דיגיטלי|Digital-wallet donor)$/.test(o.name) ? B("תורם בארנק דיגיטלי", "Digital-wallet donor") : B(o.name, o.name);
    var rec = { id: id, date: KN.todayIso(), amount: c.a, fee: c.fee, total: c.total, donor: nm, email: o.email, ref: ref, method: o.wallet || "card", fresh: true };
    S.donations.unshift(rec); S.lastDonation = rec;
    KN.log("pay", B("תרומה חדשה " + KN.moneyT(c.a) + " · " + nm.he, "New donation " + KN.moneyT(c.a) + " · " + nm.en));
    KN.notify({ kind: "payment", title: B("תרומה חדשה התקבלה", "New donation received"), body: B(nm.he + " תרם " + KN.moneyT(c.a) + " · " + DON.he + " · " + ref, nm.en + " donated " + KN.moneyT(c.a) + " · " + DON.en + " · " + ref), to: ["finance", "admin"] });
    KN.save(); return rec;
  };
  KN.act.dnPay = function (el) {
    var c = dnCalc(), wallet = el.dataset.w || "", name = (document.getElementById("dnName") || {}).value || "", email = (document.getElementById("dnEmail") || {}).value || "";
    if (!(c.a >= 1)) { KN.toast(T("בחרו סכום לתרומה", "Choose a donation amount")); return; }
    if (wallet) { name = name.trim() || T("תורם בארנק דיגיטלי", "Digital-wallet donor"); email = email.trim() || "wallet.donor@mail.demo"; }
    else {
      if (name.trim().length < 2 || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email.trim())) { KN.toast(T("כתבו שם ואימייל לקבלה", "Enter a name and an email for the receipt")); return; }
      if ((document.getElementById("dnCard").value || "").replace(/\D/g, "").length < 12) { KN.toast(T("חסר מספר כרטיס. אפשר ללחוץ ״למלא פרטי דוגמה״", "A card number is missing. You can press \"Fill sample details\"")); return; }
    }
    KN.modal('<div class="center" style="padding:20px 0"><div class="spinner"></div><h2 style="margin-top:14px">' + (wallet ? esc(wallet) + " · " : "") + T("מעבדים את התשלום", "Processing the payment") + '</h2><p class="muted" style="margin-top:6px">' + T("הדמיה בלבד. שום כרטיס אינו מחויב.", "Simulation only. No card is charged.") + "</p></div>");
    setTimeout(function () { KN.closeModal(); KN.donate({ name: name.trim(), email: email.trim(), wallet: wallet }); KN.go("thanks"); }, 1700);
  };
  function receiptMail(r) {
    var he = "<p>שלום " + esc(r.donor.he) + ",</p><p>תודה רבה על תרומתך ל" + esc(S.shul.nameHe) + ".</p><p><b>סכום התרומה:</b> " + KN.moneyT(r.amount) + (r.fee ? " (חויב " + KN.moneyT(r.total) + " כולל כיסוי עמלה)" : "") + "<br><b>מטרה:</b> " + DON.he + "<br><b>תאריך:</b> " + r.date.split("-").reverse().join(".") + "<br><b>מספר קבלה:</b> " + r.ref + "</p><p>לא ניתנו טובין או שירותים בתמורה לתרומה זו. שמרו את המייל לצורכי מס.</p><p>תזכו למצוות,<br>" + esc(S.shul.nameHe) + "</p>";
    var en = "<p>Dear " + esc(r.donor.en) + ",</p><p>Thank you for your donation to " + esc(S.shul.nameEn) + ".</p><p><b>Donation amount:</b> " + KN.moneyT(r.amount) + (r.fee ? " (charged " + KN.moneyT(r.total) + " including the fee cover)" : "") + "<br><b>Purpose:</b> " + DON.en + "<br><b>Date:</b> " + r.date + "<br><b>Receipt number:</b> " + r.ref + "</p><p>No goods or services were provided in exchange for this donation. Please keep this email for your tax records.</p><p>With thanks,<br>" + esc(S.shul.nameEn) + "</p>";
    return KN.mail({ from: KN.shulName() + " <" + S.shul.email + ">", to: r.email, subject: T("קבלה על תרומה ", "Donation receipt ") + KN.moneyT(r.amount) + " · " + r.ref, body: '<div dir="rtl">' + he + '</div><hr><div dir="ltr">' + en + "</div>" + (KN.s46Html ? KN.s46Html(r) : "") });
  }
  KN.act.receiptMail = function (el) { var r = S.donations.filter(function (d) { return d.id === el.dataset.id; })[0] || S.lastDonation || S.donations[0]; KN.modal("<h2>" + T("המייל שהתורם מקבל", "The email the donor receives") + '</h2><div style="margin-top:14px">' + receiptMail(r) + "</div>", true); };
  KN.views.thanks = {
    render: function () {
      var r = S.lastDonation || S.donations[0], mine = !!S.lastDonation;
      return '<div class="page" style="max-width:760px"><div class="card center" style="padding:34px 24px"><div class="okmark">' + ic("check") + "</div><h1>" + T("תודה רבה!", "Thank you!") + '</h1><p class="lede" style="margin:8px auto 18px">' + (mine ? T("התרומה התקבלה. קבלה למס נשלחה למייל.", "Your donation was received. A tax receipt was emailed.") : T("כך נראה דף התודה אחרי תרומה. זו תרומה לדוגמה; אפשר לתרום בעצמכם בדף התרומות.", "This is the thanks page after a donation. This one is a sample; make your own on the donate page.")) + '</p><div class="receipt"><div><span>' + T("מספר קבלה", "Receipt number") + '</span><b class="num">' + r.ref + "</b></div><div><span>" + T("שם", "Name") + "</span><b>" + esc(L(r.donor)) + "</b></div><div><span>" + T("תרומה", "Donation") + "</span><b>" + KN.money(r.amount) + "</b></div>" + (r.fee ? "<div><span>" + T("כיסוי עמלה", "Fee cover") + "</span><b>" + KN.money(r.fee) + "</b></div><div><span>" + T("חויב בסך הכול", "Total charged") + "</span><b>" + KN.money(r.total) + "</b></div>" : "") + "<div><span>" + T("מטרה", "Purpose") + "</span><b>" + L(DON) + "</b></div><div><span>" + T("תאריך", "Date") + "</span><b>" + KN.date(r.date) + ' 2026</b></div></div><p class="note" style="margin:14px 0;text-align:start">' + T("הדמיה: שום כרטיס לא חויב. כך בדיוק נראה המסך אחרי תשלום אמיתי.", "Simulation: no card was charged. This is exactly the screen after a real payment.") + '</p><div class="row" style="justify-content:center"><button class="btn sec" data-act="receiptMail" data-id="' + r.id + '">' + ic("mail") + T("לראות את מייל הקבלה", "See the receipt email") + '</button><button class="btn gold" data-act="storyFinance">' + T("המשך הסיפור: לראות את זה כגבאי כספים", "Next in the story: see it as the finance gabbai") + " " + ic("arrow") + '</button></div><p style="margin-top:14px"><button class="btn sm sec" data-go="' + (mine ? "landing" : "donate") + '">' + (mine ? T("חזרה לדף הבית", "Back to the home page") : T("לדף התרומות", "To the donate page")) + "</button></p></div>" + foot() + "</div>";
    }
  };
  KN.act.storyFinance = function () { KN.setRole("finance", "finance"); setTimeout(function () { KN.act.bell(); }, 900); };

  /* ================= join ================= */
  var jn = { step: 1 };
  function steps(cur) { var st = [T("בקשה", "Request"), T("אישור המנהל", "Admin approval"), T("ברשימת המתפללים", "In the member list"), T("מייל ברוכים הבאים", "Welcome email")]; return '<div class="row" style="gap:6px;margin-bottom:18px">' + st.map(function (s, i) { return '<span class="chip ' + (i + 1 < cur ? "ok" : i + 1 === cur ? "gold" : "") + '">' + (i + 1 < cur ? ic("check") : (i + 1) + ".") + " " + s + "</span>"; }).join("") + "</div>"; }
  KN.views.join = {
    render: function () {
      var lj = S.lastJoin, h = '<div class="page" style="max-width:820px"><div class="page-head"><div><span class="eyebrow">' + T("הצטרפות לקהילה", "Join the community") + "</span><h1>" + T("מצטרפים ל", "Join ") + esc(KN.shulName()) + '</h1><p class="lede">' + T("נכנסים עם חשבון Google, ממלאים שם וטלפון, והמנהל מאשר. בלי טפסים מנייר.", "Sign in with Google, fill in a name and a phone, and the admin approves. No paper forms.") + "</p></div></div>";
      if (lj && lj.status === "approved") return h + steps(5) + '<div class="card center"><div class="okmark">' + ic("check") + "</div><h2>" + T("ברוכים הבאים, ", "Welcome, ") + esc(L(lj.name)) + '!</h2><p class="lede" style="margin:8px auto 16px">' + T("הבקשה אושרה. עכשיו יש לכם חשבון באתר, ומייל ברוכים הבאים נשלח אליכם.", "Your request was approved. You now have an account on the site, and a welcome email was sent to you.") + '</p><div class="row" style="justify-content:center"><button class="btn" data-act="welcomeMail" data-id="' + lj.memberId + '">' + ic("mail") + T("לראות את מייל ברוכים הבאים", "See the welcome email") + '</button><button class="btn gold" data-act="jnSeeMe">' + ic("users") + T("לראות את עצמך ברשימת המתפללים", "See yourself in the member list") + '</button><button class="btn sec" data-act="jnAgain">' + T("בקשה חדשה", "A new request") + "</button></div></div>" + foot() + "</div>";
      if (lj && lj.status === "declined") return h + '<div class="card center"><h2>' + T("הבקשה לא אושרה", "The request was not approved") + '</h2><p class="lede" style="margin:8px auto 16px">' + T("במערכת האמיתית המבקש רואה את ההודעה הזאת ויכול לשלוח בקשה שוב.", "In the real system the person sees this message and may send the request again.") + '</p><button class="btn" data-act="jnAgain">' + T("לשלוח שוב", "Send again") + "</button></div>" + foot() + "</div>";
      if (lj && lj.status === "pending") return h + steps(2) + '<div class="card center"><div class="spinner" style="animation-duration:2.4s"></div><h2 style="margin-top:8px">' + T("הבקשה נשלחה וממתינה לאישור", "The request was sent and is waiting for approval") + '</h2><p class="lede" style="margin:8px auto 16px">' + esc(L(lj.name)) + " · <bdi class=\"ltr\">" + esc(lj.email) + "</bdi><br>" + T("המנהל קיבל עכשיו התראה בפעמון ובמייל.", "The admin just got a notification on the bell and by email.") + '</p><button class="btn gold" data-act="storyAdmin">' + T("המשך הסיפור: לאשר את הבקשה כמנהל", "Next in the story: approve it as the admin") + " " + ic("arrow") + "</button></div>" + foot() + "</div>";
      if (jn.step === 1) return h + steps(1) + '<div class="card center" style="padding:30px"><h2>' + T("שלב 1: כניסה", "Step 1: sign in") + '</h2><p class="lede" style="margin:8px auto 18px">' + T("במערכת האמיתית נכנסים עם חשבון Google. כך אין סיסמאות לזכור, והמייל מאומת.", "In the real system you sign in with your Google account. No passwords to remember, and the email is verified.") + '</p><button class="btn sec lg" data-act="jnGoogle"><b style="color:#4285f4;font-size:22px">G</b> ' + T("כניסה עם Google (הדמיה)", "Sign in with Google (simulated)") + "</button></div>" + foot() + "</div>";
      return h + steps(1) + '<div class="card stack"><h2>' + T("שלב 2: הפרטים שלך", "Step 2: your details") + '</h2><div class="grid g2"><div class="field"><label for="jnName">' + T("שם מלא", "Full name") + '</label><input class="input" id="jnName" value="' + T("נתנאל שרביט", "Netanel Sharvit") + '"></div><div class="field"><label for="jnPhone">' + T("טלפון", "Phone") + '</label><input class="input num" id="jnPhone" value="(555) 010-0155"></div></div><div class="field"><label for="jnEmail">' + T("אימייל (מחשבון Google)", "Email (from the Google account)") + '</label><input class="input" id="jnEmail" dir="ltr" value="netanel.sharvit@mail.demo" readonly></div><div class="field"><label for="jnNote">' + T("כמה מילים (לא חובה)", "A few words (optional)") + '</label><input class="input" id="jnNote" value="' + T("גרים ברחוב הסמוך, מתפלל אצלכם בשבתות", "We live on the next street; I daven with you on Shabbat") + '"></div><button class="btn lg" data-act="jnSend">' + T("שליחת בקשת הצטרפות", "Send the join request") + "</button></div>" + foot() + "</div>";
    }
  };
  KN.act.jnGoogle = function () { KN.modal('<div class="center" style="padding:20px 0"><div class="spinner"></div><h2 style="margin-top:14px">' + T("מתחברים עם Google", "Signing in with Google") + '</h2><p class="muted">' + T("הדמיה בלבד", "Simulation only") + "</p></div>"); setTimeout(function () { KN.closeModal(); jn.step = 2; KN.render(); KN.toast(T("נכנסת עם חשבון Google לדוגמה", "Signed in with a sample Google account")); }, 1100); };
  KN.act.jnSend = function () {
    var name = document.getElementById("jnName").value.trim(), phone = document.getElementById("jnPhone").value.trim(), email = document.getElementById("jnEmail").value.trim(), note = document.getElementById("jnNote").value.trim();
    if (name.length < 2 || phone.replace(/\D/g, "").length < 7) { KN.toast(T("כתבו שם וטלפון", "Enter a name and a phone")); return; }
    var id = "J" + Date.now(), two = function (v, he, en) { return v === he || v === en ? B(he, en) : B(v, v); }, req = { id: id, name: two(name, "נתנאל שרביט", "Netanel Sharvit"), email: email, phone: phone, when: KN.todayIso(), note: two(note, "גרים ברחוב הסמוך, מתפלל אצלכם בשבתות", "We live on the next street; I daven with you on Shabbat"), fresh: true };
    S.joinReqs.unshift(req); S.lastJoin = { id: id, name: req.name, email: email, status: "pending" };
    KN.notify({ kind: "join", title: B("בקשת הצטרפות חדשה", "New join request"), body: B("מאת " + req.name.he, "From " + req.name.en), to: ["admin"] });
    KN.log("join", B("בקשת הצטרפות: " + req.name.he, "Join request: " + req.name.en)); KN.save(); KN.render(); KN.toast(T("הבקשה נשלחה. המנהל קיבל התראה.", "Request sent. The admin was notified."));
  };
  KN.act.jnSeeMe = function () { var nm = S.lastJoin ? L(S.lastJoin.name) : ""; KN.setRole("finance", "finance/members"); setTimeout(function () { var q = document.getElementById("fq"); if (q) { q.value = nm; KN.on.fSearch(q); } }, 250); };
  KN.act.jnAgain = function () { S.lastJoin = null; jn.step = 1; KN.save(); KN.render(); };
  KN.act.storyAdmin = function () { KN.setRole("admin", "admin/join"); };

  /* ================= notifications ================= */
  var pushIdx = 0;
  KN.views.notifications = {
    render: function () {
      var base = S.notifications.slice().reverse().slice(0, 6).reverse(), kinds = { payment: T("תשלום", "Payment"), join: T("בקשת הצטרפות", "Join request"), times: T("שינוי בזמנים", "Time change"), announce: T("הודעה", "Announcement"), yahrzeit: T("יארצייט", "Yahrzeit"), approval: T("אישור", "Approval") };
      var all = S.notifications.slice(0, Math.max(6, S.notifications.length - 6 + 6)).slice(0, 9);
      return '<div class="page"><div class="page-head"><div><span class="eyebrow">' + T("התראות", "Notifications") + "</span><h1>" + T("כל אחד יודע בזמן, בלי קבוצות וואטסאפ", "Everyone knows in time, without WhatsApp groups") + '</h1><p class="lede">' + T("פעמון באתר, והתראה לטלפון גם כשהאתר סגור. כל תפקיד מקבל רק את מה שנוגע לו.", "A bell on the site, and a push to the phone even when the site is closed. Each role gets only what concerns it.") + '</p></div></div><div class="split"><div class="stack"><div class="card"><div class="card-h"><h2>' + T("הפעמון", "The bell") + '</h2><span class="chip">' + T("דוגמאות מכל הסוגים", "Samples of every kind") + '</span></div><div class="stack" style="gap:10px">' + all.map(function (n) { return '<div style="position:relative">' + KN.ntfHtml(n) + '<span class="chip gold" style="position:absolute;top:10px;inset-inline-end:10px">' + (kinds[n.kind] || "") + "</span></div>"; }).join("") + "</div></div>" +
        '<div class="card"><h2>' + T("מי מקבל מה", "Who gets what") + '</h2><div class="tw"><table class="t" style="margin-top:8px"><tr><th>' + T("אירוע", "Event") + "</th><th>" + T("מי מקבל", "Who is told") + "</th></tr>" + [[T("תשלום או תרומה התקבלו", "A payment or donation arrived"), T("גבאי הכספים והמתפלל ששילם", "The finance gabbai and the member who paid")], [T("בקשת הצטרפות חדשה", "A new join request"), T("המנהל, בפעמון ובמייל", "The admin, on the bell and by email")], [T("שינוי בזמן תפילה", "A davening time changed"), T("כל המתפללים", "All members")], [T("הודעה חדשה", "A new announcement"), T("כל המתפללים", "All members")], [T("יארצייט בשבוע הקרוב", "A yahrzeit this week"), T("המתפלל שהיארצייט שלו", "The member whose yahrzeit it is")], [T("בקשה אושרה או נדחתה", "A request was approved or declined"), T("מי ששלח את הבקשה", "The person who sent it")]].map(function (r) { return "<tr><td><b>" + r[0] + "</b></td><td>" + r[1] + "</td></tr>"; }).join("") + "</table></div></div></div>" +
        '<div class="stack"><div class="card center"><h3>' + T("התראה לטלפון", "A push to the phone") + '</h3><p class="small muted" style="margin:4px 0 16px">' + T("עובד באייפון ובאנדרואיד. בלי חנות אפליקציות: מוסיפים את האתר למסך הבית.", "Works on iPhone and Android. No app store: add the site to the home screen.") + '</p><div class="phone"><div class="scr"><div class="clock">' + KN.time("16:02").replace(/ (AM|PM)/, "") + '</div><div class="dt">' + T("יום שישי, 20 בנובמבר", "Friday, November 20") + '</div><div class="push" id="push"><span class="pi">' + KN.logo() + '</span><div><b id="pushT"></b><span id="pushB"></span></div></div></div></div><button class="btn sec" style="margin-top:18px" data-act="pushGo">' + ic("play") + T("לשלוח התראה לדוגמה", "Send a sample push") + "</button></div></div></div>" + foot() + "</div>";
    },
    after: function () { setTimeout(KN.act.pushGo, 700); }
  };
  KN.act.pushGo = function () {
    var p = document.getElementById("push"); if (!p) return;
    var list = S.notifications, n = list[pushIdx++ % list.length];
    document.getElementById("pushT").textContent = KN.shulName() + " · " + L(n.title); document.getElementById("pushB").textContent = L(n.body);
    p.classList.remove("go"); void p.offsetWidth; p.classList.add("go");
  };

  /* ================= what's included (the brochure) ================= */
  KN.views.included = {
    render: function () {
      var F = [["clock", "זמני תפילה וזמני היום", "Davening times & zmanim", "שבוע מלא של תפילות, זמני היום לפי המיקום שלכם, ושבת. הזמנים מותאמים למנהג בית הכנסת שלכם, והגבאי משנה זמן בלחיצה.", "A full week of davening, zmanim for your location, and Shabbat. The times follow your shul's custom, and the gabbai changes a time with one click.", "times"],
        ["tv", "מסך לבית הכנסת", "The shul screen", "הקדשות, יארצייט, אזכרות, מזל טוב והודעות על טלוויזיה רגילה. בשבת המסך עובר לבד למצב שבת.", "Dedications, yahrzeits, memorials, mazal tov and announcements on an ordinary TV. On Shabbat it switches by itself.", "tv"],
        ["coins", "כספים", "Finance", "נדרים ועליות, תשלומים, יתרות, דוח חודשי ומכתבי מס. הכול נרשם, שום דבר לא נמחק.", "Nedarim and aliyot, payments, balances, a monthly report and tax letters. Everything is recorded; nothing is erased.", "finance"],
        ["heart", "תרומות", "Donations", "דף תרומה בכרטיס אשראי, Apple Pay ו־Google Pay, קבלה למס במייל, וקוד QR על המסך.", "A donate page with card, Apple Pay and Google Pay, a tax receipt by email, and a QR code on the screen.", "donate"],
        ["users", "חברים", "Members", "לכל מתפלל אזור אישי: יתרה, היסטוריה, תשלום בכרטיס והיארצייטים של המשפחה. הצטרפות מהטלפון.", "Each member has his own area: balance, history, card payment and the family's yahrzeits. Joining from the phone.", "member"],
        ["bell", "התראות", "Notifications", "פעמון באתר והתראות לטלפון: תשלום, שינוי בזמנים, הודעה, יארצייט. לכל אחד מה שנוגע לו.", "A bell on the site and pushes to the phone: a payment, a time change, an announcement, a yahrzeit. Each person gets what concerns him.", "notifications"],
        ["cloud", "גיבויים", "Backups", "גיבוי אוטומטי בכל לילה, ושחזור בלחיצה. הנתונים של הקהילה שמורים ולא הולכים לאיבוד.", "An automatic backup every night, and a one-click restore. The community's data is kept safe.", "admin"],
        ["key", "תפקידים והרשאות", "Roles & permissions", "מנהל, גבאי כספים, גבאי תוכן ומתפלל. כל אחד רואה רק את מה ששייך לו, בלי סיסמאות.", "Admin, finance gabbai, content gabbai and member. Each sees only what is his, with no passwords.", "admin"],
        ["globe", "עברית ואנגלית", "Hebrew & English", "כל המערכת בשתי השפות, עם מעבר בלחיצה. עברית מימין לשמאל כמו שצריך.", "The whole system in both languages, switched with one click. Hebrew right-to-left, done properly.", "landing"],
        ["grid", "מרכז פיקוד", "Command center", "מדדים חיים, עוזר חכם שמציע את הפעולה הבאה, וקמפיין עם מד התקדמות. הכול במסך אחד.", "Live figures, a smart assistant that proposes the next action, and a campaign with a progress meter. All on one screen.", "hq", 1],
        ["scroll", "לוח עליות", "Aliyot board", "שיבוץ אוטומטי לפי חיובים ותור, דף לגבאי, ובמוצאי שבת הכול נרשם כנדרים.", "Auto-assign by chiyuv and rotation, a gabbai's sheet, and on Saturday night it all becomes nedarim.", "aliyot", 1],
        ["seat", "מפת מקומות", "Seat map", "מקומות קבועים ומכירה לימים הנוראים. לוחצים על מקום, מוכרים, והחיוב נרשם לבד.", "Permanent seats and High Holiday sales. Click a seat, sell it, and the charge records itself.", "seats", 1]];
      return '<div class="page"><div class="page-head"><div><span class="eyebrow">' + T("מה כלול · שתי דקות קריאה", "What's included · a two-minute read") + "</span><h1>" + T("מערכת אחת לכל מה שקורה בבית הכנסת", "One system for everything that happens in your shul") + '</h1><p class="lede">' + T("נכתב לנשיאים ולגבאים, לא למתכנתים. זה מה שמקבלים, ואפשר לראות כל חלק עובד כאן בהדגמה.", "Written for presidents and gabbaim, not for developers. This is what you get, and you can see each part working here in the demo.") + '</p></div><button class="btn gold" data-act="tourStart">' + ic("play") + T("סיור מודרך", "Take the tour") + '</button></div><div class="grid g3">' + F.concat(KN.MODS.map(function (m) { return [m.ic, m.he, m.en, m.dHe, m.dEn, m.id, 1, m.need || "none"]; })).map(function (f) { return '<div class="card"><div class="feat"><span class="fi">' + ic(f[0]) + "</span><div><b>" + T(f[1], f[2]) + '</b><p class="small" style="margin-top:4px">' + T(f[3], f[4]) + '</p><button class="btn sm sec" style="margin-top:10px" ' + (f[6] ? 'data-act="proGo" ' + (f[7] ? 'data-need="' + f[7] + '" ' : "") + 'data-to="' : 'data-go="') + f[5] + '">' + T("לראות בהדגמה", "See it in the demo") + " " + ic("arrow") + "</button></div></div></div>"; }).join("") + "</div>" +
        '<section class="section"><div class="reassure"><div>' + ic("cal") + T("הקמה מלווה, צעד אחר צעד", "Guided setup, step by step") + "</div><div>" + ic("tv") + T("בלי ציוד חדש, חוץ מטלוויזיה", "No new hardware, except a TV") + "</div><div>" + ic("phone") + T("עובד בכל טלפון", "Works on every phone") + "</div></div></section>" +
        '<section class="section"><span class="eyebrow">' + T("איך מתחילים", "How it starts") + '</span><div class="grid g3" style="margin-top:8px">' + [[T("מדברים", "We talk"), T("שיחה קצרה: כמה מתפללים, מה חשוב לכם, מה יש היום.", "A short call: how many members, what matters to you, what you use today.")], [T("מתאימים", "We fit it to you"), T("השם, הלוגו והצבעים שלכם, הזמנים שלכם, רשימת המתפללים.", "Your name, logo and colors, your times, your member list.")], [T("עולים לאוויר", "You go live"), T("תולים טלוויזיה, שולחים למתפללים קישור, והגבאים מתחילים לעבוד.", "Hang a TV, send the members a link, and the gabbaim start working.")]].map(function (s, i) { return '<div class="card"><span class="avatar">' + (i + 1) + '</span><h3 style="margin-top:8px">' + s[0] + '</h3><p class="small" style="margin-top:4px">' + s[1] + "</p></div>"; }).join("") + '</div><p class="center" style="margin-top:18px"><button class="btn" data-act="customize">' + ic("palette") + T("לראות את המערכת עם השם והצבעים שלכם", "See the system with your name and colors") + "</button></p></section>" + KN.cta() + foot() + "</div>";
    }
  };
})();
